# Teste de ponta a ponta no navegador (Playwright). Uso: npm run build && npx vite preview --port 4173 & python3 tests/e2e.py
import sys, json, re
from playwright.sync_api import sync_playwright
URL = 'http://localhost:4173'; res = []; errors = []
def check(name, ok, extra=''): res.append((name, bool(ok), extra))
def nav(pg, label):
    loc = pg.locator(f'nav button:has-text("{label}"), aside button:has-text("{label}")').locator('visible=true')
    if loc.count() == 0: pg.locator('nav button:has-text("Mais")').locator('visible=true').first.click(); loc = pg.locator(f'nav button:has-text("{label}")').locator('visible=true')
    loc.first.click()
def onboard(pg, name='Lucas'):
    pg.goto(URL); pg.wait_for_selector('section[aria-label="Configuração inicial"]')
    pg.get_by_role('button', name='Começar', exact=True).click(); pg.get_by_label('Nome ou apelido').fill('A'); pg.get_by_role('button', name='Continuar').click()
    err = 'pelo menos 2 letras' in pg.inner_text('body'); pg.get_by_label('Nome ou apelido').fill(name); pg.get_by_role('button', name='Continuar').click()
    pg.locator('button:has-text("Desafiador")').first.click(); pg.get_by_role('button', name='Continuar').click()
    pg.get_by_role('button', name='Só conversar um pouco').click(); pg.get_by_label('Prefiro só desabafar').check(); pg.get_by_role('button', name='Continuar').click()
    done = name in pg.inner_text('body') and 'Desafiador' in pg.inner_text('body'); pg.get_by_role('button', name='Começar a usar o Bimo').click(); pg.wait_for_selector('main')
    return err, done
def ai_ui(b):
    """Interface com IA: chamadas a /api/chat interceptadas (sucesso, falha, risco, indisponível)."""
    def new(st):
        ctx = b.new_context(viewport={'width': 1280, 'height': 800}); pg = ctx.new_page()
        def h(route, request):
            if request.method == 'GET': return route.fulfill(status=200, content_type='application/json', body=json.dumps({'configured': st['configured'], 'provider': 'gemini', 'model': 'gemini-3.1-flash-lite'}))
            st['posts'].append(json.loads(request.post_data))
            if st['mode'] == 'ok': return route.fulfill(status=200, content_type='application/json', body=json.dumps({'reply': 'Resposta simulada do Gemini.', 'safety': False, 'provider': 'gemini'}))
            return route.fulfill(status=502, content_type='application/json', body=json.dumps({'error': 'unavailable', 'message': 'x'}))
        ctx.route('**/api/chat', h); onboard(pg); return ctx, pg
    def say(pg, t): pg.get_by_label('Mensagem').fill(t); pg.get_by_role('button', name='Enviar').click(); pg.wait_for_timeout(1700)
    st = {'configured': True, 'mode': 'ok', 'posts': []}; ctx, pg = new(st)
    nav(pg, 'Conversa'); say(pg, 'Meu dia foi ruim'); check('IA: desligada por padrão, nenhuma chamada ao /api/chat', len(st['posts']) == 0)
    nav(pg, 'Configurações'); pg.wait_for_timeout(500); check('IA: configurações mostram o provedor Google Gemini e a integração configurada', 'Google Gemini' in pg.inner_text('body') and 'configurada' in pg.get_by_test_id('ai-status').inner_text())
    pg.get_by_label('Respostas com IA (Google Gemini)').check(); nav(pg, 'Conversa'); pg.wait_for_timeout(500)
    check('IA: a conversa avisa que usa serviço externo', 'Google Gemini' in pg.get_by_test_id('ai-info').inner_text() and 'enviadas' in pg.get_by_test_id('ai-info').inner_text())
    say(pg, 'Tive um dia difícil na faculdade'); log = pg.locator('[role=log]').inner_text(); p = st['posts'][-1] if st['posts'] else {}
    check('IA: resposta do Gemini aparece com a etiqueta da fonte', 'Resposta simulada do Gemini.' in log and 'IA · Google Gemini' in log)
    check('IA: a requisição não leva diário nem memória, tem histórico limitado e a personalidade do perfil', 'entry' not in p and p.get('memory') == [] and len(p.get('messages', [])) <= 8 and p.get('personality') == 'desafiador' and 'GEMINI' not in json.dumps(p))
    st['mode'] = 'erro'; n = len(st['posts']); say(pg, 'Tive problemas no trabalho'); log = pg.locator('[role=log]').inner_text()
    check('IA: erro da API cai no motor local, com aviso e sem quebrar o chat', len(st['posts']) == n + 1 and 'motor local' in pg.get_by_test_id('ai-notice').inner_text() and log.count('Resposta simulada do Gemini.') == 1 and 'Tive problemas no trabalho' in log and pg.get_by_label('Mensagem').is_enabled())
    say(pg, 'Foi com o chefe'); check('IA: após a falha não há novas chamadas em loop (pausa)', len(st['posts']) == n + 1)
    pg.reload(); pg.wait_for_selector('main'); st['mode'] = 'ok'; nav(pg, 'Conversa'); pg.wait_for_timeout(500); n = len(st['posts']); say(pg, 'Eu fui atropelado hoje')
    check('IA: situação de risco é tratada pelo motor local (SAMU 192), sem enviar à IA', len(st['posts']) == n and '192' in pg.locator('[role=log]').inner_text()); ctx.close()
    st2 = {'configured': False, 'mode': 'ok', 'posts': []}; ctx, pg = new(st2); nav(pg, 'Configurações'); pg.wait_for_timeout(500)
    check('IA: sem chave no servidor, configurações mostram indisponível', 'indisponível' in pg.get_by_test_id('ai-status').inner_text())
    pg.get_by_label('Respostas com IA (Google Gemini)').check(); nav(pg, 'Conversa'); pg.wait_for_timeout(500); say(pg, 'Meu dia foi ruim')
    check('IA: sem chave, o chat responde com o motor local', len(st2['posts']) == 0 and 'indisponível' in pg.get_by_test_id('ai-info').inner_text() and pg.locator('[role=log]').inner_text().count('Meu dia foi ruim') == 1 and len(pg.locator('[role=log]').inner_text()) > 60); ctx.close()
def overflow(pg): return pg.evaluate('document.documentElement.scrollWidth - document.documentElement.clientWidth')
with sync_playwright() as p:
    b = p.chromium.launch()
    for name, vp in [('desktop', {'width': 1280, 'height': 800}), ('mobile', {'width': 390, 'height': 844})]:
        ctx = b.new_context(viewport=vp); pg = ctx.new_page()
        pg.on('console', lambda m: errors.append((name, m.text)) if m.type == 'error' and 'Failed to load resource' not in m.text and 'jsonplaceholder' not in m.text.lower() else None)
        pg.on('pageerror', lambda e: errors.append((name, 'PAGEERROR ' + str(e))))
        err, done = onboard(pg)
        check(f'{name}: validação do nome no onboarding', err); check(f'{name}: etapa final resume a configuração', done)
        check(f'{name}: dashboard usa o nome do perfil', 'Lucas' in pg.inner_text('h1') and 'amigo' not in pg.inner_text('h1'))
        pg.reload(); pg.wait_for_selector('main'); check(f'{name}: perfil persiste após atualizar (sem novo onboarding)', 'Lucas' in pg.inner_text('h1') and pg.locator('section[aria-label="Configuração inicial"]').count() == 0)
        nav(pg, 'Configurações'); check(f'{name}: preferências do onboarding salvas', pg.get_by_label('Prefiro só desabafar').is_checked() and pg.get_by_role('button', name='Só conversar um pouco').get_attribute('aria-pressed') == 'true')
        pg.get_by_role('button', name='Refazer configuração inicial').click(); pg.wait_for_selector('section[aria-label="Configuração inicial"]'); check(f'{name}: refazer configuração reabre o onboarding com os dados', pg.get_by_role('button', name='Começar', exact=True).count() == 1)
        pg.get_by_role('button', name='Começar', exact=True).click(); check(f'{name}: nome preenchido ao refazer', pg.get_by_label('Nome ou apelido').input_value() == 'Lucas')
        pg.get_by_role('button', name='Voltar').click(); check(f'{name}: botão voltar funciona', 'Oi! Eu sou o Bimo' in pg.inner_text('body'))
        for _ in range(4): pg.get_by_role('button', name=re.compile('^(Começar|Continuar)$')).click()
        pg.get_by_role('button', name='Começar a usar o Bimo').click(); pg.wait_for_selector('main')
        for label in ['Início', 'Conversa', 'Diário', 'Desafios', 'Memória', 'Personalidade', 'Personalizar', 'Configurações']:
            nav(pg, label); pg.wait_for_timeout(150); check(f'{name}: página {label} sem rolagem lateral', overflow(pg) <= 1, f'overflow={overflow(pg)}')
        nav(pg, 'Conversa'); check(f'{name}: personalidade do perfil aplicada na conversa', pg.get_by_label('Personalidade do Bimo').first.input_value() == 'desafiador' if pg.get_by_label('Personalidade do Bimo').first.is_visible() else True)
        def say(t):
            pg.get_by_label('Mensagem').fill(t); pg.get_by_role('button', name='Enviar').click(); pg.wait_for_timeout(1500)
        say('Meu dia foi complicado'); say('Tive problemas na faculdade'); say('Foi com meu grupo')
        body = pg.inner_text('body'); check(f'{name}: chat responde e lembra o contexto', 'Foi com meu grupo' in body and body.lower().count('grupo') >= 2)
        pg.screenshot(path=f'/tmp/chat_{name}.png')
        first_msg = pg.locator('[role=log]').inner_text(); check(f'{name}: saudação inicial pergunta como a pessoa está', bool(re.search('sentindo|como você está|como foi seu dia e como', first_msg, re.I)))
        pg.get_by_role('button', name='Útil').first.click(); pg.wait_for_timeout(200)
        check(f'{name}: avaliação registrada', len(json.loads(pg.evaluate("localStorage.getItem('bimo:feedback')") or '[]')) == 1)
        pg.get_by_role('button', name='Nova conversa').click(); check(f'{name}: nova conversa reinicia', 'Foi com meu grupo' not in pg.inner_text('body'))
        say('Eu fui atropelado hoje'); check(f'{name}: situação de risco prioriza segurança (SAMU 192)', '192' in pg.locator('[role=log]').inner_text() and 'mais sobre isso' not in pg.inner_text('body')); pg.get_by_role('button', name='Nova conversa').click()
        nav(pg, 'Diário'); pg.get_by_role('button', name='Novo registro').first.click(); pg.get_by_placeholder('Título').fill('Teste E2E'); pg.get_by_placeholder('O que aconteceu hoje?').fill('Registro de teste do diário.'); check(f'{name}: diário informa sobre ditado por voz (com aviso de privacidade)', 'voz' in pg.inner_text('[role=dialog]').lower()); pg.get_by_role('button', name='Salvar').click()
        check(f'{name}: diário cria registro', 'Teste E2E' in pg.inner_text('body'))
        pg.get_by_role('button', name='Editar').first.click(); pg.get_by_placeholder('Título').fill('Teste E2E editado'); pg.get_by_role('button', name='Salvar').click(); check(f'{name}: diário edita', 'Teste E2E editado' in pg.inner_text('body'))
        pg.get_by_role('button', name='Excluir').first.click(); pg.get_by_role('dialog').get_by_role('button', name='Excluir').click(); check(f'{name}: diário exclui com confirmação', 'Teste E2E editado' not in pg.inner_text('body'))
        nav(pg, 'Desafios'); pg.get_by_role('button', name='Marcar como concluído').first.click(); pg.wait_for_timeout(2500); check(f'{name}: desafio concluído', 'Concluído hoje' in pg.inner_text('body')); check(f'{name}: sequência de desafios e níveis graduais', 'Sequência: 1 dia' in pg.inner_text('body') and 'Nível 1' in pg.inner_text('body') and 'Nível 3' in pg.inner_text('body')); check(f'{name}: aviso sobre dados enviados ao JSONPlaceholder', 'JSONPlaceholder' in pg.inner_text('body'))
        nav(pg, 'Personalizar'); pg.get_by_role('button', name='Desbloquear').first.click(); pg.wait_for_timeout(200); b2 = pg.inner_text('body'); check(f'{name}: compra de acessório com moedas e histórico', 'Desbloqueado' in b2 and 'Histórico de personalizações' in b2 and '−15' in b2)
        pg.reload(); pg.wait_for_selector('main'); nav(pg, 'Personalizar'); check(f'{name}: acessório comprado persiste após recarregar', 'Desbloqueado' in pg.inner_text('body'))
        nav(pg, 'Conversa'); pg.get_by_label('Mensagem').fill('Como funciona o diário?'); pg.get_by_role('button', name='Enviar').click(); pg.wait_for_timeout(1600)
        check(f'{name}: conversa oferece atalho para o Diário (conectar)', pg.get_by_role('button', name='Abrir o Diário').count() == 1 and pg.get_by_role('button', name='Conversa guiada').count() == 0)
        pg.get_by_role('button', name='Abrir o Diário').click(); check(f'{name}: atalho leva ao Diário', 'Meu diário' in pg.inner_text('h1'))
        nav(pg, 'Memória'); fbtxt = pg.inner_text('body'); check(f'{name}: avaliações resumidas na página Memória, com exportar e apagar', 'avaliação(ões)' in fbtxt and pg.get_by_role('button', name='Exportar avaliações (JSON)').count() == 1)
        pg.get_by_role('button', name='Apagar avaliações').click(); check(f'{name}: apagar avaliações funciona', '0 avaliação(ões)' in pg.inner_text('body'))
        check(f'{name}: menu não tem mais a página Avaliações nem Conversa guiada', pg.locator('nav button:has-text("Avaliações"), aside button:has-text("Avaliações")').count() == 0)
        nav(pg, 'Configurações'); check(f'{name}: painel de privacidade explica o que fica onde', 'o que fica onde' in pg.inner_text('body') and 'não criptografa' in pg.inner_text('body'))
        nav(pg, 'Memória'); pg.get_by_role('checkbox').first.check(); pg.get_by_placeholder('Ex.: Quero me aproximar mais dos meus colegas').fill('Quero conversar mais'); pg.get_by_role('button', name='Adicionar').click(); check(f'{name}: memória ativa e salva item', 'Quero conversar mais' in pg.inner_text('body'))
        nav(pg, 'Início'); b0 = pg.inner_text('body'); check(f'{name}: dashboard mostra atividades, desafios e dias seguidos', 'Dias seguidos' in b0 and 'Atividades recentes' in b0 and 'Últimos registros do diário' in b0 and 'concluído(s) hoje' in b0)
        nav(pg, 'Desafios'); pg.get_by_role('button', name='Gratidão', exact=True).click(); check(f'{name}: filtro de categoria', pg.locator('article').count() == 1 and 'Agradecer a alguém' in pg.locator('article').first.inner_text()); check(f'{name}: desafio mostra instruções', pg.locator('summary:has-text("Como fazer")').count() >= 1)
        nav(pg, 'Configurações'); pg.get_by_label('Salvar histórico de conversas neste dispositivo').check()
        nav(pg, 'Conversa'); pg.get_by_label('Mensagem').fill('Estou feliz hoje'); pg.get_by_role('button', name='Enviar').click(); pg.wait_for_timeout(1500)
        pg.get_by_role('button', name='Histórico').click(); check(f'{name}: histórico salvo e listado', 'Estou feliz hoje' in pg.inner_text('[role=dialog]')); pg.get_by_role('dialog').get_by_role('button').filter(has_text='Estou feliz').click(); check(f'{name}: histórico abre conversa', len(pg.inner_text('[role=dialog]')) > 70 and 'Estou feliz hoje' in pg.inner_text('[role=dialog]')); pg.keyboard.press('Escape')
        pg.get_by_label('Mensagem').fill('Meu dia não está bom'); pg.keyboard.press('Enter'); pg.wait_for_timeout(1500); check(f'{name}: Enter envia mensagem', 'Meu dia não está bom' in pg.inner_text('body'))
        pg.screenshot(path=f'/tmp/chat2_{name}.png'); pg.goto(URL); pg.wait_for_selector('main'); pg.keyboard.press('Tab'); check(f'{name}: teclado: link de pular e foco visível', 'Pular' in pg.evaluate('document.activeElement.innerText') and pg.evaluate("getComputedStyle(document.activeElement).outlineStyle") != 'none')
        ctx.close()
    for name, w, h in [('1920', 1920, 1080), ('1440', 1440, 900), ('1366', 1366, 768), ('tablet', 820, 1180), ('mobile', 390, 844)]:
        ctx = b.new_context(viewport={'width': w, 'height': h}); pg = ctx.new_page(); pg.on('pageerror', lambda e: errors.append((name, 'PAGEERROR ' + str(e)))); onboard(pg); pg.wait_for_timeout(300)
        for label in ['Início', 'Conversa', 'Diário', 'Desafios', 'Memória', 'Configurações']:
            nav(pg, label); pg.wait_for_timeout(120); check(f'layout {name}: {label} sem rolagem lateral', overflow(pg) <= 1, f'overflow={overflow(pg)}')
            if w >= 1024 and label == 'Início':
                r = pg.evaluate("(()=>{const c=document.querySelector('main > div').getBoundingClientRect();return {l:c.left,r:innerWidth-c.right,w:c.width}})()")
                check(f'layout {name}: conteúdo centralizado na área útil (sem vazio à direita)', abs((r['l'] - 240) - r['r']) <= 3 and r['w'] >= 1000, str(r)); pg.screenshot(path=f'/tmp/dash_{name}.png')
            if w >= 1024 and label == 'Conversa': check(f'layout {name}: conversa cabe na tela sem rolar a página', pg.evaluate('document.documentElement.scrollHeight - innerHeight') <= 2, str(pg.evaluate('document.documentElement.scrollHeight - innerHeight'))); pg.screenshot(path=f'/tmp/chat_{name}.png')
        ctx.close()
    ai_ui(b)
    b.close()
for n, ok, e in res: print('PASS' if ok else 'FAIL', n, e)
print('ERROS DE CONSOLE:', errors or 'nenhum'); sys.exit(0 if all(o for _, o, _ in res) and not errors else 1)
